<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {supabase} from '@/lib/supabase'
const route=useRoute(),sale=ref<any>(null),items=ref<any[]>([]),customer=ref<any>(null),error=ref('')
onMounted(async()=>{const {data,error:e}=await supabase.from('sales').select('id,receipt_no,customer_id,total,tax_amount,grand_total,payment_method,notes,created_at,sale_items(id,sale_id,product_id,quantity,price_sell,actual_price,line_total,products(name,sku)),customers(name,phone)').eq('id',String(route.params.id)).single();if(e)error.value=e.message;else{sale.value=data;items.value=data.sale_items??[];customer.value=data.customers}})
function print(){window.print()}
</script><template><section class="page-wrap"><p v-if="error" class="alert">{{error}}</p><article v-if="sale" class="panel receipt"><div class="page-heading"><div><h1>Receipt {{sale.receipt_no??sale.id}}</h1><p>{{new Date(sale.created_at).toLocaleString()}}</p></div><button class="btn" @click="print">Print / Save PDF</button></div><h2>Hybrid Shop</h2><p v-if="customer">Customer: {{customer.name}} · {{customer.phone}}</p><div class="table-scroll"><table><thead><tr><th>Item</th><th>Qty</th><th>Unit price</th><th>Total</th></tr></thead><tbody><tr v-for="i in items" :key="i.id"><td>{{i.products?.name??i.product_id}}</td><td>{{i.quantity}}</td><td>UGX {{Number(i.actual_price||i.price_sell).toLocaleString()}}</td><td>UGX {{Number(i.line_total).toLocaleString()}}</td></tr></tbody></table></div><div class="totals"><div>Subtotal <b>UGX {{Number(sale.total).toLocaleString()}}</b></div><div>Tax <b>UGX {{Number(sale.tax_amount).toLocaleString()}}</b></div><div class="grand">Grand total <b>UGX {{Number(sale.grand_total).toLocaleString()}}</b></div><div>Payment <b>{{sale.payment_method}}</b></div></div></article></section></template>
